"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["94092"],{42107(a){a.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.calendario_vigente.forma_territorial_invalida","status":422,"titulo":"O calend\xe1rio vigente traz dia com recorte territorial incoerente com a abrang\xeancia"},"descricao":{"codigo":"uniplus.selecao.calendario_vigente.forma_territorial_invalida","requisitos":["UNI-REQ-0080"],"oQueAconteceu":["A publica\xe7\xe3o foi recusada porque o calend\xe1rio de dias \xfateis vigente traz um dia cujos\\ncampos territoriais n\xe3o correspondem \xe0 abrang\xeancia declarada nele.","Cada abrang\xeancia admite um conjunto pr\xf3prio, e s\xf3 ele:","| Abrang\xeancia | Campos que o dia carrega |\\n|---|---|\\n| `NACIONAL` | nenhum \u2014 incide em todo o territ\xf3rio |\\n| `INSTITUCIONAL` | nenhum \u2014 vale para a institui\xe7\xe3o inteira |\\n| `ESTADUAL` | a UF, e nenhum campo de munic\xedpio |\\n| `MUNICIPAL` | c\xf3digo IBGE, nome e UF do munic\xedpio |","Um dia municipal que tamb\xe9m trouxesse UF estadual, ou um dia nacional com munic\xedpio,\\nseria contradit\xf3rio: dois campos afirmariam territ\xf3rios diferentes para a mesma data.","A vers\xe3o publicada congela o calend\xe1rio **por valor**, e \xe9 imut\xe1vel. Descartar em sil\xeancio\\no campo que sobra faria a contradi\xe7\xe3o do cadastro desaparecer dentro de um artefato que\\nningu\xe9m mais pode corrigir \u2014 e a vers\xe3o passaria a afirmar um territ\xf3rio que o calend\xe1rio\\nde origem n\xe3o declarou."],"comoResolver":["O dado vem do cadastro de calend\xe1rios de dias \xfateis, no m\xf3dulo Configura\xe7\xe3o, n\xe3o da\\nconfigura\xe7\xe3o do processo seletivo. Quem publica n\xe3o tem campo a corrigir aqui.","Corrija os dados na origem e publique-os novamente. O cadastro recusa cada uma dessas combina\xe7\xf5es na cria\xe7\xe3o, com erro pr\xf3prio: [dados municipais apenas para abrang\xeancia municipal](/erros/uniplus.configuracao.calendario_dias_uteis.snapshot_municipal_apenas_para_municipal), [UF apenas para estadual](/erros/uniplus.configuracao.calendario_dias_uteis.uf_apenas_para_estadual) e [UF obrigat\xf3ria para estadual](/erros/uniplus.configuracao.calendario_dias_uteis.uf_obrigatoria_para_estadual).","Um calend\xe1rio vigente que chegue nessa forma indica que ele foi gravado por caminho que n\xe3o\\npassou por essas verifica\xe7\xf5es."],"ondeAparece":["Publica\xe7\xe3o inicial do processo seletivo","Retifica\xe7\xe3o em ato \xfanico"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Calendario vigente"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"fd5ea0ff72951399d2b2c1a4f29aeb3ea415db44"}}')}}]);